import PropTypes from "prop-types";
import React from "react";

import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { compose, bindActionCreators } from "redux";
import { connect } from "react-redux";
import {
  getRealValueByType,
  isLeftConditionValid,
  isValueValid,
} from "./CommonRuleFunctions";
import { ModalManager } from "@traveloka/soya-components";
import ConditionLeftModal from "./ConditionLeftModal";
import ConditionModal from "./ConditionModal";
import ConditionRightModal from "./ConditionRightModal";
import { NotificationManager } from "@traveloka/soya-components";
import StaticLinkText from "./StaticLinkText/StaticLinkText";

import * as style from "./CommonRule.styles";

class ConditionRow extends React.Component {
  constructor(props) {
    super(props);
  }

  getLeftConditionValue() {
    const { condition, ruleStructures } = this.props;
    const structureFormat = JSON.parse(ruleStructures.formatterStructure);
    let leftValue = "";
    if (condition.leaf && condition.leaf.length > 0) {
      const format = structureFormat[condition.leaf[0].root];
      if (Object.keys(condition.leaf[0]).length > 1) {
        const fields = Object.values(format.fields);
        for (const i in format.displayFormat) {
          if (
            format.displayFormat[i].indexOf("{") !== -1 &&
            format.displayFormat[i].indexOf("}") !== -1
          ) {
            const fieldIdx = parseInt(
              format.displayFormat[i].replace(/{|}/g, ""),
              10
            );
            if (!isNaN(fieldIdx) && fieldIdx >= 0) {
              leftValue = leftValue.concat(
                condition.leaf[0][fields[fieldIdx].id]
              );
            }
          } else {
            leftValue = leftValue.concat(format.displayFormat[i]);
          }
        }
      } else {
        leftValue = format ? format.label : condition.leaf[0].root;
      }
    }
    return leftValue;
  }

  getTotalFieldsByOperator(operator) {
    const { ruleStructures } = this.props;
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    if (expressionStructure[operator]) {
      return expressionStructure[operator].input.length;
    }
    return 1;
  }

  getLeftExistingValue() {
    const { condition } = this.props;
    const existingValue = {};
    if (condition.leaf && condition.leaf.length > 0) {
      if (condition.leaf[0].root) {
        existingValue.root = condition.leaf[0].root;
      }
      for (const i in condition.leaf[0]) {
        if (i !== "root") {
          existingValue[i] = condition.leaf[0][i];
        }
      }
      return existingValue;
    }
    return null;
  }

  getRightExistingValue() {
    const { condition } = this.props;
    if (
      condition.leaf &&
      condition.leaf.length > 0 &&
      condition.leaf[0].root !== null
    ) {
      if (condition.leaf && condition.leaf.length === 2) {
        if (condition.leaf[1]) {
          const rightValue = { root: condition.leaf[1].root };
          if (condition.leaf[1].value) {
            rightValue.value = condition.leaf[1].value;
          } else {
            for (const i in condition.leaf[1]) {
              if (i !== "root") {
                rightValue[i] = condition.leaf[1][i];
              }
            }
          }
          return rightValue;
        }
      } else {
        return null;
      }
    } else {
      return null;
    }
  }

  getOperatorExistingValue() {
    const { condition } = this.props;
    return condition.root;
  }

  handleShowLeftModal = () => {
    const { condition } = this.props;
    if (condition.root) {
      ModalManager.show({
        title: `Change Left Expression`,
        body: (
          <ConditionLeftModal
            onCancel={this.handleCancelModalManager}
            onSave={this.handleChangeLeftCondition}
            operator={condition.root}
            existingValue={this.getLeftExistingValue()}
          />
        ),
        footer: " ",
      });
    } else {
      NotificationManager.showError({
        message: "Choose operator first",
        size: "md",
      });
    }
  };

  handleChangeLeftCondition = (newLeftValue) => {
    const { componentIndex, index, actions } = this.props;
    if (isLeftConditionValid(newLeftValue)) {
      const left = {};
      for (const i in newLeftValue) {
        left[i] = newLeftValue[i];
      }
      actions.editLeftCondition(componentIndex, index, left);
      ModalManager.dismiss();
    } else {
      this.notification.showError("Input is not valid, please re-check");
    }
  };

  handleChangeRightCondition = (newRightValue) => {
    const { componentIndex, index, actions } = this.props;
    if (isValueValid(newRightValue.root, newRightValue.value)) {
      const right = {
        root: newRightValue.root,
        value: getRealValueByType(newRightValue.root, newRightValue.value),
      };
      actions.editRightCondition(componentIndex, index, right);
      ModalManager.dismiss();
    } else {
      this.notification.showError("Input is not valid, please re-check");
    }
  };

  handleShowOperatorModal = () => {
    const existingValue = this.getOperatorExistingValue();
    ModalManager.show({
      title: `Change Operator`,
      body: (
        <ConditionModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleChangeOperatorCondition}
          existingValue={existingValue}
        />
      ),
      footer: " ",
    });
  };

  handleShowRightModal = () => {
    const { condition } = this.props;
    if (
      condition.leaf &&
      condition.leaf.length > 0 &&
      condition.leaf[0].root !== null
    ) {
      ModalManager.show({
        title: `Change Right Expression`,
        body: (
          <ConditionRightModal
            onCancel={this.handleCancelModalManager}
            onSave={this.handleChangeRightCondition}
            leftValue={condition.leaf[0].root}
            existingValue={this.getRightExistingValue()}
          />
        ),
        footer: " ",
      });
    } else {
      NotificationManager.showError({
        message: "Choose left expression first",
        size: "md",
      });
    }
  };

  handleNotCondition = () => {
    const { componentIndex, condition, index, actions } = this.props;
    const newCondition = { root: "Not", leaf: [condition] };
    actions.editCondition(componentIndex, index, newCondition);
  };

  handleChangeOperatorCondition = (root) => {
    const { componentIndex, index, actions } = this.props;
    const condition = root;
    condition.leaf = [];
    actions.editCondition(componentIndex, index, condition);
    ModalManager.dismiss();
  };

  handleAndCondition = () => {
    this.handleAddOperatorCondition("And");
  };

  handleOrCondition = () => {
    this.handleAddOperatorCondition("Or");
  };

  handleAddOperatorCondition = (operator) => {
    const { componentIndex, condition, index, actions } = this.props;
    const newCondition = { root: operator, leaf: [condition, {}] };
    actions.editCondition(componentIndex, index, newCondition);
  };

  handleRemoveCondition = () => {
    const { componentIndex, index, actions } = this.props;
    actions.removeCondition(componentIndex, index);
  };

  handleCancelModalManager = () => {
    ModalManager.dismiss();
  };

  displayCondition = () => {
    const { condition } = this.props;
    const leftValue = this.getLeftConditionValue();
    let rightValue;

    if (condition.leaf && condition.leaf[1]) {
      if (condition.leaf[1].value) {
        rightValue = condition.leaf[1].value;
      } else {
        if (condition.leaf[1].date) {
          rightValue = condition.leaf[1].date;
        } else {
          rightValue = null;
        }
      }
    } else {
      rightValue = null;
    }

    return (
      <div>
        {condition.root && (
          <StaticLinkText
            color={leftValue ? null : "#c1c1c1"}
            text={leftValue ? leftValue : "Select Expression"}
            onClick={this.handleShowLeftModal}
          />
        )}

        <StaticLinkText
          color={condition.root ? "#19bc80" : "#c1c1c1"}
          text={condition.root ? condition.root : "Select Operator"}
          onClick={this.handleShowOperatorModal}
        />
        {this.getTotalFieldsByOperator(condition.root) > 1 ? (
          <StaticLinkText
            color={rightValue === null ? "#c1c1c1" : null}
            text={
              rightValue === null ? "Select Expression" : rightValue.toString()
            }
            onClick={this.handleShowRightModal}
          />
        ) : null}
        {Object.keys(condition).length > 0 ? (
          <div className={style.operatorGroup}>
            <StaticLinkText text="NOT" onClick={this.handleNotCondition} />
            <StaticLinkText text="OR" onClick={this.handleOrCondition} />
            <StaticLinkText text="AND" onClick={this.handleAndCondition} />
            <StaticLinkText
              text="Remove"
              color="#F44336"
              onClick={this.handleRemoveCondition}
            />
          </div>
        ) : null}
      </div>
    );
  };

  render() {
    const { ruleStructures } = this.props;
    if (!ruleStructures) return <div />;
    return <div className={style.conditionRow}>{this.displayCondition()}</div>;
  }
}

ConditionRow.propTypes = {
  condition: PropTypes.object.isRequired,
  componentIndex: PropTypes.number.isRequired,
  index: PropTypes.number.isRequired,
  ruleStructures: PropTypes.string.isRequired,
  actions: PropTypes.object.isRequired,
};

const mapStateToProps = (state, ownProps) => ({
  ruleStructures: commonRulesSelector.getRuleStructures(state),
});

const mapDispatchToProps = (dispatch, ownProps) => ({
  actions: bindActionCreators(commonRulesMapDisToProps, dispatch),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, mapDispatchToProps)
)(ConditionRow);
